WINE=[V,['早期日耳曼语借入酒的名称 → 古英语 wīn','葡萄酒'],['中古英语 wyn/win → 英语 wine','葡萄酒；也用于其他果酒名称']]
VINEGAR=[V,['古法语 vin + aigre → vinaigre','酒 + 酸：醋'],['中古英语 vinegre → 英语 vinegar','醋']]
